import{_ as a}from"./chunks/more.BA9dr6o4.js";import{_ as t,c as o,o as r,a2 as i}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"More ways to compare","description":"Compare pictures and archives, export a comparison as an image, and adjust appearance and language.","frontmatter":{"title":"More ways to compare","description":"Compare pictures and archives, export a comparison as an image, and adjust appearance and language."},"headers":[],"relativePath":"guide/more.md","filePath":"guide/more.md","lastUpdated":1793948370000}'),s={name:"guide/more.md"};function n(c,e,d,l,p,h){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="more-ways-to-compare" tabindex="-1">More ways to compare <a class="header-anchor" href="#more-ways-to-compare" aria-label="Permalink to &quot;More ways to compare&quot;">​</a></h1><p>Text is only part of the story. qDiff opens several other kinds of content with the same side-by-side idea.</p><img src="'+a+'" alt="Two pictures compared side by side" class="guide-shot"><h2 id="pictures" tabindex="-1">Pictures <a class="header-anchor" href="#pictures" aria-label="Permalink to &quot;Pictures&quot;">​</a></h2><p>Put two images next to each other to compare them comfortably, or overlay them to see exactly where they differ — handy for design revisions and almost-identical photos.</p><h2 id="compressed-archives" tabindex="-1">Compressed archives <a class="header-anchor" href="#compressed-archives" aria-label="Permalink to &quot;Compressed archives&quot;">​</a></h2><p>A .zip or .tar archive can be opened directly and compared like a folder. No unpacking, no temporary files to clean up afterwards.</p><h2 id="files-that-are-not-plain-text" tabindex="-1">Files that are not plain text <a class="header-anchor" href="#files-that-are-not-plain-text" aria-label="Permalink to &quot;Files that are not plain text&quot;">​</a></h2><p>When two files look identical but behave differently, qDiff can compare them down to the smallest detail, including differences a text view cannot show.</p><h2 id="save-a-comparison-as-a-picture" tabindex="-1">Save a comparison as a picture <a class="header-anchor" href="#save-a-comparison-as-a-picture" aria-label="Permalink to &quot;Save a comparison as a picture&quot;">​</a></h2><p>Select a change and export it as a clean, two-column image — ready to paste into a message, a document or a review. The picture has no markings added.</p><h2 id="make-it-yours" tabindex="-1">Make it yours <a class="header-anchor" href="#make-it-yours" aria-label="Permalink to &quot;Make it yours&quot;">​</a></h2><ul><li><strong>Appearance</strong> — light and dark, following your Mac or set manually.</li><li><strong>Language</strong> — English, Simplified Chinese, Traditional Chinese and more.</li><li><strong>Fonts and shortcuts</strong> — adjust reading comfort and use the keyboard for the actions you repeat most.</li><li><strong>Recent comparisons</strong> — reopen something you looked at yesterday from the welcome screen.</li></ul><p>Everything above is included in the free version.</p><p>Have a question? <a href="./faq.html">Check the FAQ</a>.</p>',15)])])}const g=t(s,[["render",n]]);export{f as __pageData,g as default};
